"""Original, parameterised grade-nine set questions. v=0 is the canonical bank.
The six assessment versions are explicitly variants, not new learning objectives.
"""
from fractions import Fraction
from itertools import combinations, product

LEVELS = ['آسان', 'متوسط', 'دشوار', 'درخشان']
TOPICS = ['معرفی مجموعه', 'نمایش و زیرمجموعه', 'عملیات مجموعه‌ها', 'مجموعه‌ها و احتمال']

def roster(xs):
    return '{' + ', '.join(map(str, sorted(set(xs)))) + '}' if xs else '∅'

def fraction(n, d):
    return str(Fraction(n, d))

def questions(v=0):
    out = []
    def add(level, objective, topic, prompt, answer, feedback, kind='short', options=None, verify=None, graphic=None):
        qid = f'f01-{len(out)+1:02d}'
        out.append(dict(id=qid, family=qid, objective=objective, grade=9, book='ریاضی نهم', chapter='فصل اول: مجموعه‌ها',
            lesson=topic, topic=TOPICS[topic-1], difficulty=LEVELS[level-1], level=level,
            type=kind, prompt=prompt, answer=str(answer), feedback=feedback, options=options or [],
            verify=verify, graphic=graphic, variant=v, origin='تألیفی؛ هم‌راستا با اهداف کتاب', sources=[]))
    a=7+v; b=a+1; c=a+2
    A={a,b,c}; B={b,c,c+1}; C={a,c+1}
    # Foundations: distinct goals, including notation and the sample space.
    add(1,'تشخیص معیار عضویت مشخص',1,f'کدام توصیف، اعضا را به‌طور یکتا مشخص می‌کند؟',f'عددهای صحیح بین {a} و {a+4}',
        'با معیار دقیق می‌توان عضویت هر عدد را تعیین کرد؛ «خوب»، «بزرگ» و تعداد بدون تعیین اعضا کافی نیست.',
        'mcq',[f'عددهای صحیح بین {a} و {a+4}','چند بازی جالب','سه عدد بزرگ','چهار شهر دلخواه'],dict(op='literal',expected=f'عددهای صحیح بین {a} و {a+4}'))
    add(1,'تمایز عضو بودن از نبودن',1,f'اگر A={roster(A)} باشد، گزارهٔ {b} ∈ A درست است یا نادرست؟','درست','عدد موردنظر را در فهرست اعضا جست‌وجو کن؛ نماد ∈ برای عضو بودن است.','tf',verify=dict(op='member',x=b,A=sorted(A)))
    add(1,'شمارش اعضای متمایز',1,f'تعداد اعضای {{{a}, {b}, {a}, {c}, {b}}} چند است؟',3,'هر عضو تکراری فقط یک بار شمرده می‌شود.',verify=dict(op='card',A=[a,b,a,c,b]))
    add(1,'تمایز تهی از تک‌عضوی صفر',1,f'گزارهٔ ∅ = {{{v}}} درست است یا نادرست؟','نادرست',f'تهی هیچ عضوی ندارد؛ {{{v}}} یک عضو دارد.','tf',verify=dict(op='literal',expected='نادرست'))
    add(1,'تبدیل بازه صحیح به فهرست',2,f'اعضای A={{x ∈ ℤ | {a} < x < {a+4}}} را بنویس.',roster(range(a+1,a+4)),'دو کران به علت علامت < عضو نیستند؛ عددهای صحیح بین آن‌ها را بنویس.','set',verify=dict(op='interval',lo=a,hi=a+4))
    add(1,'برابری با جابه‌جایی اعضا',2,f'دو مجموعهٔ {{{a}, {b}, {c}}} و {{{c}, {a}, {b}}} برابرند.','درست','برابری به یکسان بودن اعضا وابسته است و ترتیب اثری ندارد.','tf',verify=dict(op='literal',expected='درست'))
    add(1,'بررسی زیرمجموعه بودن',2,f'اگر A={roster(A)} باشد، آیا {{{a}, {c}}} ⊆ A درست است؟','درست','برای زیرمجموعه بودن، تک‌تک اعضای مجموعهٔ کوچک‌تر باید در A باشند.','tf',verify=dict(op='subset',A=[a,c],B=sorted(A)))
    n=2+v
    add(1,'تعداد همه زیرمجموعه‌ها',2,f'مجموعه‌ای با {n} عضو متمایز چند زیرمجموعه دارد؟',2**n,'برای هر عضو دو انتخاب داریم: در زیرمجموعه باشد یا نباشد؛ حاصل 2ⁿ است.',verify=dict(op='subsets',n=n))
    add(1,'اجتماع دو فهرست',3,f'برای A={roster(A)} و B={roster(B)}، اعضای A ∪ B را بنویس.',roster(A|B),'اعضای هر دو مجموعه را یک بار بنویس؛ عضو مشترک را دوباره نشمار.','set',verify=dict(op='union',A=sorted(A),B=sorted(B)))
    add(1,'اشتراک دو فهرست',3,f'برای A={roster(A)} و B={roster(B)}، اعضای A ∩ B را بنویس.',roster(A&B),'فقط عضوهایی را نگه دار که هم در A و هم در B هستند.','set',verify=dict(op='intersection',A=sorted(A),B=sorted(B)))
    add(1,'تفاضل جهت‌دار',3,f'برای A={roster(A)} و B={roster(B)}، اعضای A − B را بنویس.',roster(A-B),'از اعضای A شروع کن و هر عضو موجود در B را حذف کن؛ جهت تفاضل مهم است.','set',verify=dict(op='difference',A=sorted(A),B=sorted(B)))
    k=1+v
    add(1,'شمارش فضای نمونه آزمایش مرکب',4,f'{k} سکهٔ سالم را همراه یک تاس سالم شش‌وجهی می‌اندازیم. تعداد حالت‌های هم‌شانس چند است؟',6*2**k,'هر سکه دو حالت و تاس شش حالت دارد؛ تعداد حالت‌ها در هم ضرب می‌شود.',verify=dict(op='sample',coins=k,dice=1))
    t=v if v else 2
    add(1,'احتمال ساده با تاس سالم',4,f'تاس سالمی می‌اندازیم. احتمال اینکه عدد رو‌شده حداکثر {t} باشد چقدر است؟',fraction(t,6),'حالت‌های مطلوب 1 تا کران داده‌شده‌اند؛ آن‌ها را بر شش حالت هم‌شانس تقسیم کن.',verify=dict(op='die_threshold',t=t))
    add(1,'احتمال پیشامد ناممکن',4,f'در پرتاب تاس استاندارد سالم، احتمال رو شدن عدد {9+v} چقدر است؟',0,'تاس استاندارد فقط 1 تا 6 دارد؛ پیشامد بدون حالت مطلوب، احتمال صفر دارد.',verify=dict(op='literal',expected='0'))
    # Intermediate: transformations, Venn counts, and compound sample spaces.
    add(2,'اثر نگاشت خطی بر اعضا',2,f'A={{2x+{v+1} | x ∈ {{1,2,3}}}} را با اعضا بنویس.',roster(2*x+v+1 for x in [1,2,3]),'به‌جای x هر عضو دامنه را جداگانه بگذار؛ خودِ xها پاسخ نیستند.','set',verify=dict(op='image_linear',m=2,b=v+1,domain=[1,2,3]))
    add(2,'بازیابی پارامتر در برابری',2,f'اگر {{2x+1, {a+20}}} = {{{a}, {a+20}}}، مقدار x چند است؟',fraction(a-1,2),'عضو ثابت را کنار بگذار و 2x+1 را با عضو دیگر برابر کن.',verify=dict(op='equality',target=a,fixed=a+20))
    d=[12,18,20,24,28,30,36][v]
    add(2,'نمایش مجموعه شمارنده‌ها',2,f'مجموعهٔ شمارنده‌های طبیعی مثبت {d} را بنویس.',roster(x for x in range(1,d+1) if d%x==0),'هر عدد مثبت که تقسیم بر آن باقیماندهٔ صفر می‌دهد، عضو است؛ 1 و خود عدد را فراموش نکن.','set',verify=dict(op='divisors',n=d))
    add(2,'تمایز عضو از زیرمجموعه در مجموعه تودرتو',2,f'اگر A={{{a}, {{{b}}}}} باشد، کدام گزاره درست است؟',f'{{{b}}} ∈ A','در اینجا مجموعهٔ تک‌عضوی خودش یک عضو A است؛ b به‌تنهایی عضو A نیست.','mcq',[f'{{{b}}} ∈ A',f'{b} ∈ A',f'{{{b}}} ⊆ A',f'{a} ⊆ A'],dict(op='literal',expected=f'{{{b}}} ∈ A'))
    n=4+v
    add(2,'شمارش زیرمجموعه‌های دو عضوی',2,f'یک مجموعهٔ {n} عضوی چند زیرمجموعهٔ دقیقاً دو عضوی دارد؟',n*(n-1)//2,'هر جفتِ بدون ترتیب یک زیرمجموعه است؛ هر جفت را دوبار نشمار.',verify=dict(op='pairs',n=n))
    x,y,z=8+v,6+v,3+v
    add(2,'شمارش اجتماع با حذف هم‌پوشانی',3,f'n(A)={x+z}، n(B)={y+z} و n(A∩B)={z}. مقدار n(A∪B) چند است؟',x+y+z,'جمع دو تعداد، اشتراک را دوبار می‌شمارد؛ آن را یک بار کم کن.',verify=dict(op='regions',x=x,y=y,z=z,what='union'))
    opts=[f'A={{{a}}}, B={{{b}}}',f'A=∅, B={{{b}}}',f'A={{{a}}}, B={{{a}, {b}}}',f'A={{{a}}}, B={{{a}}}']
    add(2,'ساخت مثال نقض برای برداشت نادرست از اشتراک تهی',3,'برای رد گزارهٔ «اگر A∩B=∅، آنگاه A⊆B»، کدام زوج یک مثال نقض است؟',opts[0],
        'مثال نقض باید شرط را درست و نتیجه را نادرست کند: دو تک‌عضوی متفاوت اشتراک تهی دارند، اما اولی زیرمجموعهٔ دومی نیست.',
        'mcq',opts,dict(op='counterexample',a=a,b=b))
    add(2,'شمارش فقط گروه اول',3,f'از {x+z} عضو گروه A، تعداد {z} نفر عضو B هم هستند. چند نفر در A−B قرار دارند؟',x,'اعضای مشترک را از تعداد A کم کن؛ فقط A خواسته شده است.',verify=dict(op='regions',x=x,y=y,z=z,what='only_a'))
    outside=4+v
    add(2,'شمارش بیرون دو مجموعه',3,f'کلاسی {x+y+z+outside} نفره است؛ {x+z} نفر در A و {y+z} نفر در B هستند و {z} نفر در هر دو. چند نفر در هیچ‌کدام نیستند؟',outside,'ابتدا اندازهٔ اجتماع را پیدا کن و سپس از کل کلاس کم کن.',verify=dict(op='regions',x=x,y=y,z=z,outside=outside,what='neither'))
    add(2,'خواندن ناحیه‌های نمودار ون',3,'در نمودار ون، اعضای B−A را بنویس.',roster([c+1]),'بخش فقط B را بخوان؛ ناحیهٔ مشترک در تفاضل قرار نمی‌گیرد.','set',verify=dict(op='difference',A=sorted(B),B=sorted(A)),graphic=dict(A=sorted(A-B),both=sorted(A&B),B=sorted(B-A)))
    m=15+v
    add(2,'احتمال متمم در انتخاب کارت',4,f'یکی از کارت‌های یکسان با شماره‌های 1 تا {m} را با شانس برابر برمی‌داریم. احتمال اینکه شماره مضرب 3 نباشد؟',fraction(m-m//3,m),'ابتدا مضرب‌های 3 را بشمار؛ تعداد نامطلوب را از کل کم کن.',verify=dict(op='cards',n=m,predicate='not3'))
    k=2+v
    add(2,'احتمال دقیقاً یک رو با سکه‌ها',4,f'{k} سکهٔ سالم و مستقل را می‌اندازیم. احتمال دقیقاً یک «رو» چقدر است؟',fraction(k,2**k),'حالت‌های رو/پشت هم‌شانس‌اند؛ دقیقاً یک جایگاه برای رو انتخاب می‌شود.',verify=dict(op='coins',n=k,condition='one'))
    total=5+v
    cnt=sum(i+j==total for i in range(1,7) for j in range(1,7))
    add(2,'احتمال مجموع مشخص دو تاس',4,f'دو تاس سالم با رنگ متفاوت می‌اندازیم. احتمال مجموع {total} چقدر است؟',fraction(cnt,36),'زوج‌های مرتب را بشمار؛ برای مثال (2,3) و (3,2) دو حالت متفاوت‌اند.',verify=dict(op='dice',condition='sum',target=total))
    m=18+v
    cnt=sum(i%2==0 and i%3==0 for i in range(1,m+1))
    add(2,'احتمال اشتراک دو شرط',4,f'از کارت‌های یکسان شمارهٔ 1 تا {m} یکی انتخاب می‌شود. احتمال زوج بودن و مضرب 3 بودن شماره؟',fraction(cnt,m),'«و» یعنی هر دو شرط هم‌زمان؛ مضرب‌های 6 را در بازه بشمار.',verify=dict(op='cards',n=m,predicate='and23'))
    # Hard: multi-stage set operations and inverse probability.
    n=5+v
    add(3,'زیرمجموعه با عضو اجباری و ممنوع',2,f'A دارای {n} عضو متمایز است و a و b دو عضو متفاوت آن‌اند. چند زیرمجموعه a را دارند و b را ندارند؟',2**(n-2),'وضعیت a و b ثابت است؛ برای اعضای باقی‌مانده دو انتخاب داریم.',verify=dict(op='constrained_subsets',n=n,condition='include_exclude'))
    add(3,'بازسازی مجموعه از ناحیه‌های ون',3,f'A−B={roster([a])}، A∩B={roster([b,c])} و B−A={roster([c+1])}. مجموعهٔ B را بنویس.',roster(B),'B از ناحیهٔ مشترک و ناحیهٔ فقط B تشکیل می‌شود؛ فقط A را وارد نکن.','set',verify=dict(op='rebuild',both=[b,c],only=[c+1]))
    add(3,'تفاضل از اشتراک',3,f'A={roster(A)} و B={roster(B)}. حاصل A−(A∩B) را بنویس.',roster(A-(A&B)),'ابتدا پرانتز را محاسبه کن و سپس اعضای آن را از A حذف کن.','set',verify=dict(op='nested',A=sorted(A),B=sorted(B),C=sorted(C),expression='a_minus_inter'))
    add(3,'اشتراک با اجتماع سه مجموعه',3,f'A={roster(A)}، B={roster(B)} و C={roster(C)}. حاصل A∩(B∪C)؟',roster(A&(B|C)),'ابتدا اجتماع داخل پرانتز، سپس اشتراک با A؛ ترتیب محاسبه را حفظ کن.','set',verify=dict(op='nested',A=sorted(A),B=sorted(B),C=sorted(C),expression='distribute'))
    add(3,'تشخیص همانی تفاضل',3,'کدام عبارت برای همهٔ مجموعه‌های A و B برابر A−B است؟','A−(A∩B)','از A فقط عضوهای مشترک با B حذف می‌شوند؛ تفاضل جابه‌جایی‌پذیر نیست.','mcq',['A−(A∩B)','B−A','A∩B','A∪B'],dict(op='identity'))
    x,y=3+v,8+v
    add(3,'برابری دو مجموعه با دو مجهول',2,f'اگر x و y عدد صحیح باشند و {{2x+1, {2*y}}}={{{2*x+1}, y+{y}}}، مقدار x چند است؟',x,'2x+1 فرد است و با عضو زوج ثابت برابر نمی‌شود؛ آن را با عضو فرد سمت راست برابر کن.',verify=dict(op='two_parameter',x=x,y=y))
    n=3+v
    add(3,'بازیابی تعداد اعضا از تعداد زیرمجموعه‌ها',2,f'مجموعهٔ A دارای {2**n} زیرمجموعه است. چند عضو دارد؟',n,'تعداد زیرمجموعه‌ها 2ⁿ است؛ توان مناسب 2 را پیدا کن.',verify=dict(op='inverse_subsets',n=n))
    m=24+v
    add(3,'اجتماع دو شرط با هم‌پوشانی',4,f'از کارت‌های 1 تا {m} با شانس برابر انتخاب می‌کنیم. احتمال مضرب 2 یا مضرب 3 بودن؟',fraction(sum(i%2==0 or i%3==0 for i in range(1,m+1)),m),'مضرب‌های 6 در هر دو گروه‌اند؛ در اجتماع فقط یک بار شمرده می‌شوند.',verify=dict(op='cards',n=m,predicate='or23'))
    add(3,'پیشامد دقیقاً یکی از دو شرط',4,f'از کارت‌های یکسان 1 تا {m} یکی انتخاب می‌شود. احتمال اینکه شماره دقیقاً یکی از شرط‌های مضرب 2 و مضرب 3 را داشته باشد؟',fraction(sum((i%2==0)!=(i%3==0) for i in range(1,m+1)),m),'دقیقاً یکی یعنی حالت مشترک پذیرفته نیست؛ اشتراک را از هر دو گروه حذف کن.',verify=dict(op='cards',n=m,predicate='xor23'))
    t=6+v
    cnt=sum(i+j==t or i==j for i in range(1,7) for j in range(1,7))
    add(3,'احتمال اجتماع در فضای زوج‌های مرتب',4,f'دو تاس سالم رنگی می‌اندازیم. احتمال اینکه مجموع {t} شود یا دو عدد یکسان باشند؟',fraction(cnt,36),'دو پیشامد را فهرست کن و زوج‌های مشترک را در اجتماع دوبار نشمار.',verify=dict(op='dice',condition='sum_or_double',target=t))
    t=v if v else 2
    cnt=sum(h==1 or d<=t for h in [0,1] for d in range(1,7))
    add(3,'اجتماع شرط سکه و تاس',4,f'یک سکهٔ سالم و یک تاس سالم را مستقل می‌اندازیم. احتمال «سکه رو باشد یا عدد تاس حداکثر {t} باشد»؟',fraction(cnt,12),'فضای نمونه 12 زوج دارد؛ حالت‌های دارای هر دو شرط را فقط یک بار بشمار.',verify=dict(op='coin_die',t=t))
    red,blue=3+v,4+v
    add(3,'احتمال دو برداشت بدون جایگذاری',4,f'کیسه‌ای {red} مهرهٔ قرمز و {blue} مهرهٔ آبی هم‌اندازه دارد. دو مهره را تصادفی و بدون بازگرداندن برمی‌داریم. احتمال دو قرمز؟',fraction(red*(red-1),(red+blue)*(red+blue-1)),'پس از برداشت اول، هم تعداد قرمزها و هم کل مهره‌ها یک واحد کم می‌شود.',verify=dict(op='draw',red=red,blue=blue))
    r=3+v
    add(3,'بازیابی تعداد از احتمال',4,f'کیسه‌ای {r} مهرهٔ قرمز و تعدادی آبی هم‌اندازه دارد. احتمال انتخاب قرمز 1/3 است. چند مهرهٔ آبی دارد؟',2*r,'تعداد قرمز بر کل برابر 1/3 است؛ کل سه برابر قرمزهاست و آبی‌ها باقی‌مانده‌اند.',verify=dict(op='inverse_bag',red=r))
    n,na,nb=20+v,12+v,13+v
    add(3,'کران کمینهٔ هم‌پوشانی',3,f'در گروه {n} نفره، {na} نفر عضو A و {nb} نفر عضو B هستند. حداقل چند نفر در هر دو هستند؟',na+nb-n,'اگر اشتراک کمتر باشد، اجتماع از کل گروه بیشتر می‌شود؛ از n(A)+n(B)−کل استفاده کن.',verify=dict(op='min_overlap',N=n,a=na,b=nb))
    # Enrichment within finite sets: explicit regions make all assumptions visible.
    regions=[2+v,3+v,4+v,2,3,1,1+v]
    a0,b0,c0,ab,ac,bc,abc=regions
    sizes=dict(A=a0+ab+ac+abc,B=b0+ab+bc+abc,C=c0+ac+bc+abc,AB=ab+abc,AC=ac+abc,BC=bc+abc,ABC=abc)
    labels={'A':'A','B':'B','C':'C','AB':'A∩B','AC':'A∩C','BC':'B∩C','ABC':'A∩B∩C'}
    desc='؛ '.join(f'n({labels[name]})={val}' for name,val in sizes.items())
    add(4,'اصل شمول و عدم شمول سه مجموعه',3,f'{desc}. تعداد اعضای اجتماع سه مجموعه چند است؟',sum(regions),'تعدادهای تکی را جمع، اشتراک‌های دوتایی را کم و اشتراک سه‌تایی را یک بار اضافه کن.',verify=dict(op='triple',regions=regions,what='union'))
    add(4,'شمارش عضویت دقیقاً در یک گروه',3,f'{desc}. چند عضو دقیقاً در یکی از سه مجموعه‌اند؟',a0+b0+c0,'از هر تعداد تکی، اشتراک‌های دوتایی را حذف کن؛ اشتراک سه‌تایی در بازسازی ناحیه‌ها جبران می‌شود.',verify=dict(op='triple',regions=regions,what='one'))
    add(4,'شمارش عضویت دقیقاً در دو گروه',3,f'{desc}. چند عضو دقیقاً در دو مجموعه‌اند؟',ab+ac+bc,'جمع اشتراک‌های دوتایی، اعضای هر سه را سه بار می‌شمارد؛ سه برابر اشتراک سه‌تایی را کم کن.',verify=dict(op='triple',regions=regions,what='two'))
    total=sum(regions)+5+v
    add(4,'شمارش بیرون اجتماع سه گروه',3,f'کل افراد {total} نفرند و {desc}. چند نفر در هیچ گروهی نیستند؟',5+v,'ابتدا اجتماع سه مجموعه را با جبران اشتراک‌ها حساب کن؛ سپس آن را از کل کم کن.',verify=dict(op='triple',regions=regions,N=total,what='none'))
    n=5+v
    add(4,'زیرمجموعه با حداقل یکی از دو عضو',2,f'A دارای {n} عضو است و a و b دو عضو متفاوت آن‌اند. چند زیرمجموعه دست‌کم یکی از a و b را دارند؟',2**n-2**(n-2),'از همهٔ زیرمجموعه‌ها، مواردی را کم کن که هیچ‌یک از آن دو عضو را ندارند.',verify=dict(op='constrained_subsets',n=n,condition='atleast_one'))
    add(4,'شمارش زوج زیرمجموعه‌های زنجیره‌ای',2,f'اگر A دارای {2+v} عضو باشد، چند زوج مرتب (B,C) داریم که B⊆C⊆A؟',3**(2+v),'هر عضو سه وضعیت دارد: بیرون C، فقط در C، یا در B و C؛ زوج‌ها مرتب‌اند.',verify=dict(op='subset_chain',n=2+v))
    n=2+v
    add(4,'برابری مجموعه با برخورد پارامترها',2,f'برای چند مقدار حقیقی x، مجموعهٔ {{x², {n*n}}} با {{{n*n}}} برابر می‌شود؟',2,'هر دو عبارت سمت چپ باید همان عضو یکتا شوند؛ x²=n² دو ریشهٔ متمایز دارد.',verify=dict(op='collision',n=n))
    n=3+v
    add(4,'اثر نگاشت چندبه‌یک بر تعداد اعضا',2,f'A={{x² | x∈ℤ و −{n}≤x≤{n}}}. تعداد اعضای A چند است؟',n+1,'x و −x مربع یکسان دارند؛ مربع‌های متمایز از صفر تا n² را بشمار.',verify=dict(op='square_image',n=n))
    add(4,'مرز آکولاد در مجموعه‌های تودرتو',1,'تعداد اعضای A={∅, {∅}, {{∅}}} چند است؟',3,'سه شیء متفاوت داریم؛ تعداد اعضای درون هر شیء را به جای تعداد اعضای A نشمار.',verify=dict(op='literal',expected='3'))
    n=3+v
    add(4,'زوجیت مجموع اعضای زیرمجموعه',2,f'چند زیرمجموعه از {{1,2,…,{n}}} مجموع اعضای زوج دارند؟ مجموع تهی را صفر بگیر.',2**(n-1),'با افزودن یا حذف عضو 1، زیرمجموعه‌های مجموع‌زوج و مجموع‌فرد جفت می‌شوند.',verify=dict(op='even_subset_sum',n=n))
    add(4,'تشخیص فضای نمونه غیرهم‌شانس',4,'در پرتاب دو تاس سالم، چرا نباید احتمال مجموع 2 را 1/11 گرفت؟','مجموع‌ها هم‌شانس نیستند','فضای هم‌شانس 36 زوج مرتب است؛ مجموع 2 فقط از زوج (1,1) حاصل می‌شود.','mcq',['مجموع‌ها هم‌شانس نیستند','چون تاس فقط دو وجه دارد','چون همهٔ مجموع‌ها احتمال صفر دارند','چون ترتیب تاس‌ها تعداد حالت‌ها را کم می‌کند'],dict(op='literal',expected='مجموع‌ها هم‌شانس نیستند'))
    n=3+v
    add(4,'شمارش زوج زیرمجموعه‌های مجزا',2,f'A دارای {n} عضو است. چند زوج مرتب (B,C) از زیرمجموعه‌های A داریم که B∩C=∅؟',3**n,'هر عضو یا فقط در B است، یا فقط در C، یا در هیچ‌کدام؛ حضور هم‌زمان مجاز نیست.',verify=dict(op='disjoint_pairs',n=n))
    k=3+v
    cnt=sum(sum(bits)>=2 for bits in product([0,1],repeat=k))
    add(4,'احتمال حداقل دو رو با متمم',4,f'{k} سکهٔ سالم و مستقل می‌اندازیم. احتمال حداقل دو رو چقدر است؟',fraction(cnt,2**k),'از همهٔ حالت‌ها، بدون رو و دقیقاً یک رو را حذف کن؛ «حداقل» شامل دو، سه و بیشتر است.',verify=dict(op='coins',n=k,condition='atleast_two'))
    deg=60+15*v
    add(4,'احتمال با ناحیه‌های غیرهم‌اندازه',4,f'چرخنده‌ای منصفانه نسبت به زاویه، یک ناحیهٔ قرمز با زاویهٔ {deg} درجه دارد و باقی آبی است. احتمال قرمز؟',fraction(deg,360),'در چرخندهٔ یکنواخت زاویه‌ای، اندازهٔ زاویه مهم است؛ صرفاً دو رنگ بودن احتمال را نصف نمی‌کند.',verify=dict(op='spinner',degrees=deg))
    return out

