    ('ساخت مثال نقض','عملیات مجموعه‌ها','با یک مثال نشان بده A−B لزوماً با B−A برابر نیست.','مثلاً A={1,4} و B={4,9}: آنگاه A−B={1} و B−A={9}.',['تعریف دو مجموعهٔ مشخص','محاسبهٔ هر دو تفاضل','نابرابر بودن دو حاصل']),
